public class WordUtils_abbreviate_TriageGen2Test {









    @Test
    public void testAbbreviate_UpperLessThanLower() {
        // upper < lower triggers upper = lower
        // str="abc", lower=2, upper=1 -> upper becomes 2. index of space is -1.
        // result = substring(0, 2) + appendToEnd
        assertEquals("ab...", WordUtils.abbreviate("abc", 2, 1, "..."));
    }












}

