package org.apache.commons.lang;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_abbreviate_TriageGen2Test {

















    @Test
    public void testAbbreviate_SpaceFoundBeforeUpper() {
        // index <= upper. result = substring(0, index) + appendToEnd
        // "Hello World", lower=0, upper=10. index of space is 5.
        // index(5) is not > upper(10) is false, so it goes to else branch
        // wait, if index is 5 and upper is 10, index <= upper.
        // The logic: if (index > upper) ... else { result.append(str.substring(0, index)); ... }
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 10, "..."));
    }




}

