public class WordUtils_abbreviate_TriageGen2Test {



















    @Test
    public void testAbbreviate_SpaceFoundExactlyAtUpper() {
        // index == upper triggers the 'else' branch
        // "Hello World", lower=0, upper=5. index is 5.
        // result = substring(0, 5) + "..." -> "Hello..."
        assertEquals("Hello...", WordUtils.abbreviate("Hello World", 0, 5, "..."));
    }


}

