public class WordUtils_abbreviate_TriageGen2Test {





















    @Test
    public void testAbbreviate_LowerBoundary() {
        // Test with lower parameter affecting space search
        // "A B C", lower=2. index of space starting from 2 is 3.
        // upper=4. index(3) <= upper(4). result = substring(0, 3) + "..." -> "A B..."
        assertEquals("A B...", WordUtils.abbreviate("A B C", 2, 4, "..."));
    }
}
